WITH valid AS (SELECT *, COALESCE(rating, 0) AS rating_filled, COALESCE(city, 'DIRECT') AS city_clean FROM suppliers WHERE city IS DISTINCT FROM 'Berlin') SELECT id, country, city, rating_filled, city_clean, ROUND(rating / SUM(rating) OVER (PARTITION BY city), 4) AS rating_share, NTILE(10) OVER (PARTITION BY country ORDER BY rating_filled DESC, id) AS rating_filled_bucket, FIRST_VALUE(rating_filled, TRUE) OVER w_grp AS first_known_rating_filled, LAST_VALUE(city, TRUE) OVER (ORDER BY rating_filled, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_city FROM valid WHERE rating > 3.3 WINDOW w_grp AS (PARTITION BY country, city ORDER BY rating_filled, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
